{
  "command": "cd apps/native/src-tauri && grep -n -A3 -B1 -E '^name = \"(russh|pageant|windows|windows-sys|tauri|webview2-com|getrandom)\"' Cargo.lock && cargo tree -i pageant -e normal && cargo tree -i 'windows@0.62.2' -e normal",
  "timeout": 60
}

{
  "command": "cd apps/native/src-tauri && git diff -- Cargo.toml Cargo.lock && git status --short -- Cargo.toml Cargo.lock && ls -la target/debug/deps 2>/dev/null | head -20",
  "timeout": 30
}

{
  "reason": "progress_update",
  "message": "Evidence confirms apps/native/src-tauri/Cargo.toml directly pins russh 0.62.5; Cargo.lock resolves russh -> pageant 0.2.1 -> windows 0.62.2, alongside windows 0.61.3. Coexistence is normal Cargo behavior, not itself an ABI conflict. Working tree already has native SSH edits; recommendation will keep them untouched and require loader attribution before any dependency change."
}

{
  "command": "git diff --cached --quiet; printf 'cached_exit=%s\\n' \"$?\"; cd apps/native/src-tauri && sed -n '2690,2712p;3258,3293p;5104,5142p' Cargo.lock",
  "timeout": 30
}

{
  "command": "cd apps/native/src-tauri && cargo tree --target x86_64-pc-windows-msvc -i pageant -e normal && cargo tree --target x86_64-pc-windows-msvc -i 'windows@0.62.2' -e normal && cargo tree --target x86_64-pc-windows-msvc -i 'windows@0.61.3' -e normal",
  "timeout": 60
}
